// One output item per PDF attachment that matches an account's `match` rules, plus
// one per email for accounts with `link.enabled` whose statement arrives as a
// download link instead of an attachment (fetched by the next node).
//
// `match` is a rule object or a list of them (any rule may match). Per rule, all
// case-insensitive; empty fields are ignored and every non-empty field must match:
//   from     – substring of the sender address / display name
//   to       – substring of the To header (e.g. statements+julia@ plus-addressing)
//   subject  – regex against the subject
//   filename – regex against the attachment filename (not usable for link accounts)
//   label    – a Gmail label on the email, by name, whole name, e.g. "Rob" (set by hand to tell apart
//              mail that nothing in the headers can: the scan paths of Manual Scan / Pete / Julia add
//              the label names; the hourly trigger does not)
// A rule with no fields never matches. If several accounts match, the one with the
// most matching fields wins. Emails that match nothing are dropped.
//
// Forwards from TRUSTED_FORWARDERS are unwrapped: the original sender, subject and
// recipient are read from the "Forwarded message" block, so a one-off manual forward
// is matched exactly as the original email would have been.
const TRUSTED_FORWARDERS = ['pete@vanheerden.ch', 'julia@vanheerden.ch'];
const MAX_LINKS = 15;

// Account list (match rules, folders, link settings; no secrets) from the sidecar.
// Fetched here, and the emails arrive as this node's input, so there is no lookup of
// other nodes by name and a failure is loud instead of silently matching nothing.
const accounts = await this.helpers.httpRequest({ method: 'GET', url: 'http://pdf-decrypt:8080/accounts', json: true });
const FIELDS = ['from', 'to', 'subject', 'filename', 'label'];

const asRules = (m) => (Array.isArray(m) ? m : m ? [m] : []);
const fieldsOf = (r = {}) => FIELDS.filter((k) => (r[k] || '').trim() !== '');

function ruleScore(r, mail) {
  const keys = fieldsOf(r);
  if (keys.length === 0) return 0;
  const ok = keys.every((k) => {
    if (k === 'label') return (mail.labels || []).some((l) => String(l).toLowerCase() === r[k].trim().toLowerCase());
    if (k === 'from' || k === 'to') return mail[k].toLowerCase().includes(r[k].trim().toLowerCase());
    return new RegExp(r[k], 'i').test(mail[k]);
  });
  return ok ? keys.length : 0;
}

// Best score across an account's rules (0 = no match). For link emails there is
// no attachment, so a rule that needs a filename cannot apply.
const score = (m, mail, noFilename) =>
  Math.max(0, ...asRules(m).map((r) => (noFilename && (r.filename || '').trim() ? 0 : ruleScore(r, mail))));

const hdr = (v, alt) =>
  [
    ...((v && v.value) || []).map((x) => `${x.name || ''} <${x.address || ''}>`),
    (v && v.text) || '',
    typeof v === 'string' ? v : '',
    alt || '',
  ].join(' ');

const stripTags = (h) =>
  h
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');

// Reads the quoted header block of a forward. Handles Gmail ("---------- Forwarded
// message ---------" then From:/Date:/Subject:/To:) and Outlook ("From: / Sent: / To:
// / Subject:" at the top of the body, labels often wrapped as *From:*), including
// values that wrap onto the next line (e.g. a long address after "<").
// A trusted address is only believed if the receiving server (Google) recorded an
// aligned authentication pass for that address's domain: SPF passed with a matching
// envelope sender, or DKIM passed for the domain. A forged "From: julia@..." from
// outside fails this, so its forwarded block is not trusted (and the mail goes unmatched).
function authenticated(headers, domain) {
  const raw = (headers || {})['authentication-results'];
  const ours = (Array.isArray(raw) ? raw : [raw])
    .flatMap((h) => String(h || '').split(/(?=authentication-results:)/i))
    .find((h) => /mx\.google\.com/i.test(h)); // the first header is the one our own server added
  if (!ours) return false;
  const ar = ours.toLowerCase();
  const d = domain.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // SPF passed for an envelope sender in the trusted domain (exact domain, not a look-alike)
  const spf = ar.includes('spf=pass') && new RegExp(`smtp\\.mailfrom=(?:[^\\s;@]+@)?${d}(?=[\\s;]|$)`).test(ar);
  // ...or DKIM passed with a signing identity in the trusted domain
  const dkim = new RegExp(`dkim=pass[^;]*header\\.[id]=@?${d}(?=[\\s;]|$)`).test(ar);
  return spf || dkim;
}

function unwrapForward(mail, body, headers) {
  const forwarder = TRUSTED_FORWARDERS.find((f) => mail.from.toLowerCase().includes(f.toLowerCase()));
  if (!forwarder || !authenticated(headers, forwarder.split('@')[1])) return mail;
  const marker = body.match(/(?:Forwarded message|Original Message)\s*-{3,}/i);
  const from0 = marker ? marker.index : 0;
  const win = body.slice(from0, from0 + 3000);
  const start = win.search(/\*?From\s*:\*?/i);
  if (start < 0 || start > (marker ? 200 : 600)) return mail;

  const labels = [...win.slice(start).matchAll(/\*?\b(From|Sent|Date|To|Cc|Bcc|Subject)\s*:\*?/gi)];
  const got = {};
  for (let i = 0; i < labels.length; i++) {
    const key = labels[i][1].toLowerCase();
    if (key in got) break;
    const valueStart = labels[i].index + labels[i][0].length;
    const rest = win.slice(start);
    let value;
    if (key === 'subject' || i === labels.length - 1) {
      value = rest.slice(valueStart).split('\n')[0];
    } else {
      value = rest.slice(valueStart, labels[i + 1].index);
    }
    got[key] = value.replace(/\s+/g, ' ').replace(/<\s+/g, '<').replace(/\s+>/g, '>').trim();
    if (key === 'subject') break;
  }
  return {
    from: got.from || mail.from,
    // keep BOTH recipients: the forward's own To (e.g. statements+rob@) selects the
    // account for plus-addressed rules, the original To is what the sender used.
    to: `${mail.to} ${got.to || ''}`.trim(),
    subject: got.subject || mail.subject,
    // when the ORIGINAL email was sent (Gmail "Date:", Outlook "Sent:"), not when it was forwarded
    date: dateFromText(got.date || got.sent || ''),
  };
}

// (The Code node sandbox has no URL class, so the host is read with a pattern.)
const hostOf = (u) => {
  const m = String(u).match(/^https?:\/\/(?:[^\/?#@]*@)?([^\/?#:]+)/i);
  return m ? m[1].toLowerCase() : '';
};

function linksOf(html, text, allow) {
  const urls = new Set();
  for (const m of (html || '').matchAll(/href\s*=\s*["']([^"']+)["']/gi)) urls.add(m[1].replace(/&amp;/g, '&'));
  for (const m of (text || '').matchAll(/https?:\/\/[^\s<>"')\]]+/g)) urls.add(m[0]);
  return [...urls].filter((u) => {
    const h = hostOf(u);
    return /^https?:/i.test(u) && allow.some((a) => h === a || h.endsWith('.' + a));
  });
}

const safeName = (s) => s.replace(/[\\/:*?"<>|#%]/g, '_').trim();

// The statement's own date, read from text such as the original file name.
// Recognised: 2026-10-02 / 2026_10_02, 20261007, 25092026 (DDMMYYYY), 18 SEP 2026,
// 01Jul2026-31Jul2026 (a range: the later date), and month-only forms (Oct_2026,
// SEPTEMBER 2026, 202610 -> "2026-10"). Returns "YYYY-MM-DD", "YYYY-MM" or ''.
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const daysIn = (y, m) => new Date(Date.UTC(y, m, 0)).getUTCDate();
function dateFromText(text) {
  const t = String(text || '');
  const full = [];
  const monthOnly = [];
  const add = (list, y, m, d) => {
    y = +y; m = +m; d = d == null ? null : +d;
    if (y < 2000 || y > 2100 || m < 1 || m > 12) return;
    if (d !== null && (d < 1 || d > daysIn(y, m))) return;
    list.push([y, m, d || 0]);
  };
  for (const m of t.matchAll(/(?<!\d)(20\d{2})[-_./](\d{2})[-_./](\d{2})(?!\d)/g)) add(full, m[1], m[2], m[3]);
  for (const m of t.matchAll(/(?<!\d)(\d{8})(?!\d)/g)) {
    const s = m[1];
    const before = full.length;
    if (s.startsWith('20')) add(full, s.slice(0, 4), s.slice(4, 6), s.slice(6, 8)); // YYYYMMDD
    if (full.length === before) add(full, s.slice(4, 8), s.slice(2, 4), s.slice(0, 2)); // DDMMYYYY
  }
  for (const m of t.matchAll(/(?<!\d)(\d{1,2})[ _-]?([A-Za-z]{3,9})[ _-]?(20\d{2})(?!\d)/g)) {
    const mo = MONTHS[m[2].slice(0, 3).toLowerCase()];
    if (mo) add(full, m[3], mo, m[1]);
  }
  // "Oct 14, 2026" / "Wed, Oct 14, 2026 at 10:08 PM" (Gmail forward headers)
  for (const m of t.matchAll(/(?<![A-Za-z])([A-Za-z]{3,9})\.? (\d{1,2}),? (20\d{2})(?!\d)/g)) {
    const mo = MONTHS[m[1].slice(0, 3).toLowerCase()];
    if (mo) add(full, m[3], mo, m[2]);
  }
  for (const m of t.matchAll(/(?<!\d)([A-Za-z]{3,9})[ _-]?(20\d{2})(?!\d)/g)) {
    const mo = MONTHS[m[1].slice(0, 3).toLowerCase()];
    if (mo) add(monthOnly, m[2], mo, null);
  }
  for (const m of t.matchAll(/(?<!\d)(20\d{2})(0[1-9]|1[0-2])(?!\d)/g)) add(monthOnly, m[1], m[2], null);
  const latest = (l) => l.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]).pop();
  const p2 = (n) => String(n).padStart(2, '0');
  if (full.length) { const [y, mo, d] = latest(full); return `${y}-${p2(mo)}-${p2(d)}`; }
  if (monthOnly.length) { const [y, mo] = latest(monthOnly); return `${y}-${p2(mo)}`; }
  return '';
}

// Saved file name. Per-account `statements.filename_template` overrides the default.
// Tokens: {date} the statement's own date when its file name (or, for link statements,
// the subject) contains one, otherwise the email date (set `statements.date_source` to
// "email" to always use the email date); {emaildate} always the email date; {year},
// {month} from {date}; {key} account key; {name} account name; {subject} the email
// subject; {original} the original file name without its .pdf extension (the email
// subject for link statements). Keep {original} (or something equally unique) in a
// template: same-named files replace each other. ".pdf" is always appended.
const DEFAULT_TEMPLATE = '{date}_{key}_{original}';
function tokensFor(cfg, account, emailDate, originalName, subject) {
  const found = cfg.date_source === 'email' ? '' : dateFromText(originalName);
  const date = found || emailDate;
  return {
    date, emaildate: emailDate, year: date.slice(0, 4), month: date.slice(5, 7),
    key: account, name: cfg.name || account, subject: safeName(subject), original: safeName(originalName).replace(/\.pdf$/i, ''),
  };
}
function nameFor(template, tokens) {
  const s = safeName(
    (template || DEFAULT_TEMPLATE).replace(/\{(\w+)\}/g, (m, k) => (k in tokens ? tokens[k] : m)),
  );
  return /\.pdf$/i.test(s) ? s : `${s}.pdf`;
}
const out = [];

// Emails from the hourly Gmail Trigger or the manual Scan Inbox (whichever ran).
const emails = $input.all();

emails.forEach((item, index) => {
  const j = item.json;
  const body = j.text || stripTags(j.html || j.textAsHtml || '');
  const mail0 = unwrapForward(
    { from: hdr(j.from, j.From), to: hdr(j.to, j.To), subject: j.subject || j.Subject || '' },
    body,
    j.headers,
  );
  mail0.labels = Array.isArray(j.labels) ? j.labels : [];
  const parsed = new Date(j.date || j.Date || Number(j.internalDate) || Date.now());
  const receivedDay = (isNaN(parsed) ? new Date() : parsed).toISOString().slice(0, 10);
  // for a forward, the date the original email was sent (if it could be read), else when it arrived
  const day = /^\d{4}-\d{2}-\d{2}$/.test(mail0.date || '') ? mail0.date : receivedDay;
  const folderOf = (cfg, account) => {
    const folder = (cfg.onedrive_folder || '').replace(/^\/+|\/+$/g, '');
    if (!folder) throw new Error(`Account ${account} has no onedrive_folder in private-config.json`);
    return folder;
  };
  const pathOf = (folder, fileName) => [...folder.split('/'), fileName].map(encodeURIComponent).join('/');
  // Where to PUT the file. A folder id wins over the path, so folders can be moved or
  // renamed in OneDrive: first a `folder_id` set in the config, then the id the workflow
  // recorded earlier for this path, else the path itself (Graph creates missing folders and
  // the response tells the next node the id to record). `drive_id` only matters for a folder
  // in someone else's drive.
  const targetOf = (cfg, folder, fileName) => {
    const recorded = cfg.recorded || {};
    const source = cfg.folder_id ? 'config' : recorded.folder_id ? 'recorded' : 'path';
    const folderId = source === 'config' ? cfg.folder_id : recorded.folder_id || '';
    const driveId = source === 'config' ? cfg.drive_id || '' : recorded.drive_id || '';
    const drive = driveId ? `drives/${encodeURIComponent(driveId)}` : 'me/drive';
    const uploadUrl = folderId
      ? `https://graph.microsoft.com/v1.0/${drive}/items/${encodeURIComponent(folderId)}:/${encodeURIComponent(fileName)}:/content`
      : `https://graph.microsoft.com/v1.0/me/drive/root:/${pathOf(folder, fileName)}:/content`;
    return { uploadUrl, folderSource: source, folderId, driveId, recordedPath: recorded.seen_path || '' };
  };

  // Which mailbox the email came from (the Scan Pete/Julia branches tag it) and whether the account
  // wants its emails deleted once filed. An email with a PDF that matched no account must never be
  // purged: it may hold something else (a receipt, a tax invoice), so Mail Outcome checks the flag.
  const mailbox = j.mailbox || 'statements';
  // Says which email a file came from, for the failure/summary mails (open it in the right account)
  const MAILBOXES = { statements: 'statements@vanheerden.ch', pete: 'pete@vanheerden.ch', julia: 'julia@vanheerden.ch' };
  const emailInfo =
    `"${(mail0.subject || '(no subject)').trim().slice(0, 90)}" from ${mail0.from.trim().slice(0, 80)}, ${receivedDay}, ${mailbox} mailbox ` +
    `https://mail.google.com/mail/?authuser=${MAILBOXES[mailbox] || ''}#all/${j.id}`;
  let attached = false;
  let pdfCount = 0;
  const emitted = [];
  for (const bin of Object.values(item.binary || {})) {
    const original = bin.fileName || 'statement.pdf';
    // judge by the attachment's real type/name: `original` falls back to 'statement.pdf' for unnamed
    // attachments (inline images), which must not count as a PDF
    const isPdf = bin.mimeType === 'application/pdf' || /\.pdf$/i.test(bin.fileName || '');
    if (!isPdf) continue;
    pdfCount++;

    const mail = { ...mail0, filename: original };
    const hit = Object.entries(accounts)
      .map(([k, a]) => [k, a, score(a.match, mail, false)])
      .filter((x) => x[2] > 0)
      .sort((a, b) => b[2] - a[2])[0];
    if (!hit) continue;

    const [account, cfg] = hit;
    const folder = folderOf(cfg, account);
    // Banks reuse the same attachment name every month, so the template carries the date.
    const fileName = nameFor(cfg.filename_template, tokensFor(cfg, account, day, original, mail0.subject));
    attached = true;
    const o = {
      json: { account, folder, fileName, uploadPath: pathOf(folder, fileName), ...targetOf(cfg, folder, fileName), messageId: j.id, mailbox, emailInfo, purge: !!cfg.purge_email, subject: mail0.subject, from: mail0.from.trim() },
      binary: { data: bin },
      pairedItem: { item: index },
    };
    emitted.push(o);
    out.push(o);
  }

  if (attached) {
    emitted.forEach((o) => { o.json.hasUnmatchedPdf = pdfCount > emitted.length; });
    return;
  }

  // No matching attachment: look for accounts whose statement is a download link.
  const hit = Object.entries(accounts)
    .filter(([, a]) => a.link && a.link.enabled)
    .map(([k, a]) => [k, a, score(a.match, mail0, true)])
    .filter((x) => x[2] > 0)
    .sort((a, b) => b[2] - a[2])[0];
  if (!hit) return;

  const [account, cfg] = hit;
  const urls = linksOf(j.html || j.textAsHtml, j.text, cfg.link.allow_hosts || []).slice(0, MAX_LINKS);
  if (urls.length === 0) return;

  const folder = folderOf(cfg, account);
  const fileName = nameFor(cfg.filename_template, tokensFor(cfg, account, day, mail0.subject || 'statement', mail0.subject));
  out.push({
    json: { account, folder, fileName, uploadPath: pathOf(folder, fileName), ...targetOf(cfg, folder, fileName), messageId: j.id, mailbox, emailInfo, purge: !!cfg.purge_email, hasUnmatchedPdf: pdfCount > 0, subject: mail0.subject, from: mail0.from.trim(), viaLink: true, linkCandidates: urls },
    pairedItem: { item: index },
  });
});

return out;

// For statements that arrive as a download link: fetch the PDF so the rest of the
// chain (decrypt -> OneDrive) sees it like an attachment. Other items pass through.
// Safety: Match only passes links on the account's allowed hosts; here a download
// is accepted only if it really is a PDF and within the size limit. A link email
// that yields no PDF fails the run loudly instead of being skipped.
const MAX_BYTES = 50 * 1024 * 1024;
// (The Code node sandbox has no URL class, so the host is read with a pattern.)
const hostOf = (u) => {
  const m = String(u).match(/^https?:\/\/(?:[^\/?#@]*@)?([^\/?#:]+)/i);
  return m ? m[1] : '?';
};

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.json.viaLink) {
    out.push({ json: item.json, binary: item.binary, pairedItem: { item: i } });
    continue;
  }

  let pdf = null;
  const tried = [];
  for (const url of item.json.linkCandidates) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url,
        encoding: 'arraybuffer',
        returnFullResponse: true,
        ignoreHttpStatusCode: true,
        timeout: 30000,
        headers: { 'User-Agent': 'Mozilla/5.0' },
      });
      const buf = Buffer.from(res.body);
      if (res.statusCode === 200 && buf.length <= MAX_BYTES && buf.subarray(0, 5).toString() === '%PDF-') {
        pdf = buf;
        break;
      }
      tried.push(`${hostOf(url)} -> HTTP ${res.statusCode}, not a usable PDF`);
    } catch (e) {
      tried.push(`${hostOf(url)} -> ${e.message}`);
    }
  }
  if (!pdf) {
    throw new Error(`No PDF found behind any link in "${item.json.subject}" for ${item.json.account} (tried: ${tried.join('; ')})`);
  }
  const binary = await this.helpers.prepareBinaryData(pdf, item.json.fileName, 'application/pdf');
  out.push({ json: item.json, binary: { data: binary }, pairedItem: { item: i } });
}
return out;

// After a successful upload: add the file to the sidecar's ledger of filed statements (feeds the
// monthly summary and tells Run Summary which files are new), and remember which OneDrive folder
// it landed in, so later
// uploads address it by id and survive the folder being moved or renamed. Graph's reply
// to the PUT names the parent folder (id, drive, current path).
//
// Records when the upload went by path (first run, or onedrive_folder was changed) and
// updates the last-seen path when a recorded folder has moved. A folder id set in the
// config is never touched. Failing to record is not fatal: the file is already filed and
// the next run simply looks the folder up by path again.
const seenPathOf = (ref) => {
  const m = String(ref.path || '').match(/root:(.*)$/);
  return m ? m[1].replace(/^\/+|\/+$/g, '') : '';
};

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const ctx = $('Fetch Linked PDFs').itemMatching(i).json;
  const ref = items[i].json.parentReference || {};
  const seenPath = seenPathOf(ref);
  const result = {
    account: ctx.account,
    fileName: ctx.fileName,
    folder: seenPath || ctx.folder,
    folderSource: ctx.folderSource,
    recorded: false,
    filed: true,
    isNew: false,
    messageId: ctx.messageId,
    mailbox: ctx.mailbox,
    purge: ctx.purge,
    hasUnmatchedPdf: ctx.hasUnmatchedPdf,
  };

  const moved = ctx.folderSource === 'recorded' && seenPath && seenPath !== ctx.recordedPath;
  if (moved) result.movedTo = seenPath;
  if ((ctx.folderSource === 'path' || moved) && ref.id) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `http://pdf-decrypt:8080/folder-id?account=${encodeURIComponent(ctx.account)}`,
        body: ctx.folderSource === 'path'
          ? { folder_id: ref.id, drive_id: ref.driveId || '', seen_path: seenPath }
          : { folder_id: ctx.folderId, drive_id: ctx.driveId, seen_path: seenPath },
        json: true,
      });
      result.recorded = true;
    } catch (e) {
      result.recordError = e.message;
    }
  }
  out.push({ json: result, pairedItem: { item: i } });
}

// Ledger: one call for the whole run. A failure here only loses the "new" flags and the
// monthly count for these files; the files are filed.
if (out.length > 0) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://pdf-decrypt:8080/filed',
      body: { entries: out.map((o) => ({ account: o.json.account, file_name: o.json.fileName, folder: o.json.folder })) },
      json: true,
    });
    const fresh = new Set(res.new || []);
    out.forEach((o) => { o.json.isNew = fresh.has(`${o.json.account}|${o.json.fileName}`); });
  } catch (e) {
    out.forEach((o) => { o.json.ledgerError = e.message; });
  }
}
return out;

// Upload failures, one input item per failed file (the error output of Upload to OneDrive).
// Turned into one failure row each; Run Summary collects them with the decrypt failures, so a
// moved folder produces one mail and one failure at the end of the run, not one per file.
//
// "The specified item name already exists" (409) is not a failure: the pre-check could not
// compare the file (it timed out), the upload refused to overwrite, and so the file is already
// in the folder. It becomes a SKIPPED row, "exists, not compared", and its email counts as filed.
//
// 404/410 on a folder id (from the config or recorded earlier) means the folder is gone:
// never silently recreate the path, tell the user which account, id and path. Other errors
// (401/403 access, 429/5xx service) are reported as such; no recorded id is ever cleared
// because of them.
const rows = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const ctx = $('Fetch Linked PDFs').itemMatching(i).json;
  const err = items[i].json.error || items[i].json;
  // the HTTP node does not always carry a status code, so fall back to the message text
  const status =
    Number(err.httpCode) ||
    Number((String(err.message).match(/\b([45]\d{2})\b/) || [])[1]) ||
    (/could not be found|not found/i.test(String(err.message)) ? 404 : 0);
  const exists = status === 409 || /already exists|nameAlreadyExists/i.test(`${err.description || ''} ${err.message || ''}`);
  const gone = ctx.folderSource !== 'path' && (status === 404 || status === 410);
  let line;
  if (exists) {
    rows.push({
      json: {
        skipped: true, uncompared: true, account: ctx.account, fileName: ctx.fileName, folder: ctx.folder,
        messageId: ctx.messageId, mailbox: ctx.mailbox, purge: ctx.purge, hasUnmatchedPdf: ctx.hasUnmatchedPdf,
      },
      pairedItem: { item: i },
    });
    continue;
  }
  if (gone) {
    line = (
      `${ctx.account}: "${ctx.fileName}" was not filed. The ${ctx.folderSource === 'config' ? 'configured folder_id' : 'recorded folder id'} ` +
        `${ctx.folderId} no longer exists (HTTP ${status}). Configured path: ${ctx.folder}. ` +
        `Last known location: ${ctx.recordedPath || 'unknown'}. ` +
        `Fix: set statements.folder_id to the folder's current id, or delete this account's entry in state/statement-folder-ids.json ` +
        `to look the path up again, then run Manual Scan (re-uploads of files already filed are skipped).`
    );
  } else if (!status && /timed? ?out|abort|econn|etimedout|enotfound|socket|network|offline/i.test(String(err.message))) {
    // no HTTP answer at all: the connection to OneDrive dropped or timed out (already retried by the node)
    line = (
      `${ctx.account}: "${ctx.fileName}" was not filed. The connection to OneDrive failed (${err.message}). ` +
        `This is usually a temporary network or OneDrive problem, not a missing folder: run Manual Scan again, ` +
        `and look closer only if the same file fails twice.`
    );
  } else if (status === 429 || status >= 500) {
    line = (
      `${ctx.account}: "${ctx.fileName}" was not filed. OneDrive returned ${status} (${folderWhere(ctx)}): ${err.message || JSON.stringify(err)}. ` +
        `OneDrive is throttling or having trouble, which is usually temporary: run Manual Scan again.`
    );
  } else {
    line = (
      `${ctx.account}: "${ctx.fileName}" was not filed. OneDrive returned ${status || 'an error'} (${folderWhere(ctx)}): ${err.message || JSON.stringify(err)}. ` +
        `This is an access problem, not a missing folder. Check the OneDrive credential and the folder's sharing, then run Manual Scan.`
    );
  }
  rows.push({ json: { failure: 'folder', line: `${line}\n  Email: ${ctx.emailInfo}`, messageId: ctx.messageId, mailbox: ctx.mailbox }, pairedItem: { item: i } });
}
function folderWhere(ctx) {
  return ctx.folderSource === 'path' ? `by path ${ctx.folder}` : `folder id ${ctx.folderId}`;
}
return rows;

// Decrypt failures, one input item per failed file (the error output of Decrypt PDF).
// Turned into one failure line each; Failure Summary collects them with the upload
// failures and sends a single alert, so one bad password no longer stops the rest of the run.
// The sidecar's message names the account and says how many passwords it tried; it never
// contains a password.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const ctx = $('Fetch Linked PDFs').itemMatching(i).json;
  const err = items[i].json.error || items[i].json;
  const why = err.description || err.message || JSON.stringify(err);
  out.push({
    json: {
      failure: 'decrypt',
      messageId: ctx.messageId,
      mailbox: ctx.mailbox,
      line:
        `${ctx.account}: "${ctx.fileName}" could not be decrypted and was not filed: ${why}\n` +
        `  Email: ${ctx.emailInfo}\n` +
        `  Then run Manual Scan (re-uploads are skipped, only the failed files are filed).`,
    },
    pairedItem: { item: i },
  });
}
return out;

// Runs once, after everything else: files filed (Record Folder), files skipped because they were
// already in OneDrive, upload and decrypt failures, and files that clash with a different file of
// the same name all arrive here through the Collect Results merge, which waits for every branch.
//
// An email is sent when something failed (always) or when this was a manual scan (so the full
// result of a scan you started is in your inbox). A scheduled/hourly run where everything went
// fine stays silent; the files it filed show up in the monthly summary. Nothing to report
// (e.g. a scan that matched no statements) stops here.
const rows = $input.all().map((i) => i.json);
const byName = (a, b) => (a.account + a.fileName).localeCompare(b.account + b.fileName);
const filed = rows.filter((j) => j.filed).sort(byName);
const skipped = rows.filter((j) => j.skipped).sort(byName);
const failures = rows.filter((j) => j.failure && j.line);
const manual = ['Manual Scan', 'Manual Scan Pete', 'Manual Scan Julia'].some((name) => $(name).isExecuted);
const marked = $('Mail Outcome').isExecuted ? $('Mail Outcome').all().map((i) => i.json) : [];
if (failures.length === 0 && !manual) return [];

const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const head =
  (manual ? 'Manual scan finished: ' : 'Statement run finished: ') +
  `${plural(filed.length, 'file')} filed, ${skipped.length} skipped (already in OneDrive)` +
  (failures.length ? `, ${failures.length} NOT filed.` : '.');

const parts = [head];
if (failures.length) parts.push('NOT FILED\n\n' + failures.map((j) => j.line).join('\n\n'));
if (marked.length) {
  const ok = marked.filter((m) => m.outcome === 'filed');
  const purged = ok.filter((m) => m.purge).length;
  parts.push(
    `Emails: ${ok.length} labelled Statements/Filed` + (purged ? ` (${purged} of them moved to Trash: purge_email is set)` : '') +
      `, ${marked.length - ok.length} labelled Statements/Failed.`,
  );
}
if (filed.length) parts.push('FILED\n' + filed.map((j) => `- ${j.account}: ${j.fileName}\n    -> ${j.folder}`).join('\n'));
if (skipped.length) {
  parts.push('SKIPPED (identical file already in the folder)\n' + skipped.map((j) => `- ${j.account}: ${j.fileName}${j.uncompared ? '  (exists; the check timed out so it was not compared)' : ''}`).join('\n'));
}
const labelFails = ['Statements', 'Pete', 'Julia']
  .map((who) => [who, $(`Mark ${who}`).isExecuted ? $(`Mark ${who}`).all().filter((i) => i.json.error).length : 0])
  .filter(([, n]) => n > 0);
if (labelFails.length) {
  parts.push('Note: could not label ' + labelFails.map(([who, n]) => `${n} email${n === 1 ? '' : 's'} in the ${who} mailbox`).join(', ') +
    '. Check the Gmail credential on that mailbox\'s Labels / Create Labels / List Labels / Mark / Trash nodes.');
}
if (filed.some((j) => j.ledgerError)) parts.push('Note: the filed-statements ledger could not be updated, so the monthly summary will miss these files.');

const subject = failures.length
  ? `Bank statements: ${plural(failures.length, 'file')} not filed`
  : `Bank statements: manual scan, ${filed.length} filed, ${skipped.length} skipped`;

return [
  {
    json: {
      subject,
      body: parts.join('\n\n'),
      failed: failures.length,
      failureText: failures.map((j) => j.line).join('\n\n'),
    },
  },
];

// Before filing: the exact size of each decrypted PDF, and the URL that says whether a file with
// the target name is already in OneDrive (Check Existing asks Graph for it). The binary is passed
// on, because the HTTP node that follows drops it.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const bytes = await this.helpers.getBinaryDataBuffer(i, 'data');
  const ctx = $('Fetch Linked PDFs').itemMatching(i).json;
  out.push({
    json: { decryptedSize: bytes.length, checkUrl: ctx.uploadUrl.replace(/:\/content$/, '') },
    binary: items[i].binary,
    pairedItem: { item: i },
  });
}
return out;

// Per file, after Check Existing asked Graph about the target name:
//   404                         -> not there yet: upload it (Upload uses conflictBehavior=fail, so it
//                                  can never overwrite anything)
//   200, same size              -> already filed: skip (listed as skipped in the summary)
//   200, different size         -> a DIFFERENT file with this name exists: do not overwrite, do not
//                                  guess; report it as a failure so you decide (delete or rename the
//                                  old one, then Manual Scan)
//   anything else / no answer   -> could not check: try the upload anyway; if the name exists after
//                                  all, Graph refuses (409) and that is reported
// Size is compared because the Code node cannot hash files; the same statement decrypts to the same
// bytes, so an identical statement has an identical size.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const m = $('Measure').itemMatching(i);
  const ctx = $('Fetch Linked PDFs').itemMatching(i).json;
  const res = items[i].json;
  const status = Number(res.statusCode) || 0;
  const body = res.body && typeof res.body === 'object' ? res.body : {};
  const decryptedSize = m.json.decryptedSize;
  const base = { ...ctx, decryptedSize };
  const paired = { item: i };

  if (status === 200 && body.file) {
    if (body.size === decryptedSize) {
      out.push({ json: { ...base, action: 'skip', skipped: true, existingSize: body.size }, binary: m.binary, pairedItem: paired });
    } else {
      out.push({
        json: {
          ...base,
          action: 'conflict',
          failure: 'exists-different',
          line:
            `${ctx.account}: "${ctx.fileName}" already exists in OneDrive (${ctx.folder}) with different content ` +
            `(existing ${body.size} bytes, new ${decryptedSize} bytes), so the new file was NOT filed and the existing one was left alone. ` +
            `If the new one is the right one, delete or rename the old file in OneDrive and run Manual Scan.\n  Email: ${ctx.emailInfo}`,
        },
        pairedItem: paired,
      });
    }
  } else {
    out.push({ json: { ...base, action: status === 404 ? 'new' : 'unchecked' }, binary: m.binary, pairedItem: paired });
  }
}
return out;

// Gmail gives label ids; turn them into names (looked up once, in the node before the scan) so match rules can use
// `label`, and tag the mailbox so Mail Outcome marks the email in the right place
